	@Test
	void thrownEvaluationCannotPublishOrReplayAnEarlierSuccessfulPrefix() throws Exception {
		try (Fixture fixture = new Fixture("ordinal", "text", "result")) {
			RuntimeException failure = new IllegalStateException("actual recipe failure");
			fixture.afterEvaluation = row -> {
				if (fixture.evaluations.get() == 2) {
					throw failure;
				}
			};
			CopyBinding copy = fixture.countedCopy(call(FN.STRING_LENGTH.stringValue(), Var.of("text")), 2);
			RowState row = fixture.row();
			ValuesRow first = fixture.values(1, "a"), second = fixture.values(2, "bb");
			try (RowCursor cursor = new ExtensionCursor(SlotPlan.values(new ValuesRow[] { first, second }).open(row),
					new CopyBinding[] { copy }, row)) {
				assertTrue(row.advance(cursor));
				assertThatThrownBy(cursor::next).isSameAs(failure);
			}
			assertThat(row.boundMask()).isZero();
			assertTrue(row.bind(1, first.values[1]));
			assertThatThrownBy(() -> copy.value(row)).isSameAs(failure);
			assertThat(fixture.evaluations).hasValue(2);
		}
	}

